const range=(k,label,min,max,step=1)=>`<label>${label}<input data-setting="${k}" type="range" min="${min}" max="${max}" step="${step}"></label>`;
const color=(k,label)=>`<label>${label}<input data-setting="${k}" type="color"></label>`;
export function buildUI(){return `<main><section id="home" class="home"><p class="eyebrow">LOCAL • REALTIME • WEBGL</p><h1>HAND MOTION<br/><i>VISUAL FX</i></h1><p class="lead">手の動きで、映像を彫刻する。</p><div class="cards"><article><div class="preview cube">◈</div><h2>MODE A / Gesture FX</h2><p>ジェスチャーでARオブジェクト、透明化を制御。</p><button id="startA">START GESTURE FX</button></article><article><div class="preview geo">◇</div><h2>MODE B / Hand Geometry</h2><p>両手の指先から映像フレームと立体を生成。</p><button id="startB">START GEOMETRY FX</button></article></div><p id="error" class="error"></p></section><section id="studio" hidden><header><button id="back">← HOME</button><strong>HAND MOTION / <span id="status">STANDBY</span></strong><div><button id="flip">CAMERA</button><button id="fullscreen">FULL</button><button id="shot">SHOT</button><button id="record">REC</button></div></header><div class="layout"><aside class="modes"><p>MODE SELECT</p>${[['cube','Hand Cube AR'],['invisible','Invisible 2.0'],['dissolve','Particle Dissolve'],['frame','Hand Frame / 8-bit'],['twist','Hand Twist'],['volume','Hand Volume'],['anime','Anime Frame']].map(([v,n])=>`<button data-mode="${v}">${n}</button>`).join('')}</aside><section id="stage"><video id="camera" playsinline muted></video><canvas id="output"></canvas><canvas id="three"></canvas><canvas id="overlay"></canvas><div class="hint">OPEN: Invisible / FIST: Restore<br/>2 hands: frame</div></section><aside class="controls"><p>PARAMETERS</p><div data-mode-panel="cube">${range('size','CUBE SIZE',.4,2,.1)}${range('speed','ROTATION',.1,3,.1)}${range('follow','FOLLOW SMOOTHING',1,12,1)}${range('opacity','OPACITY',.1,1,.05)}${color('cubeColor','CUBE COLOR')}<label class="check"><input data-setting="wireframe" type="checkbox"> WIREFRAME</label></div><div data-mode-panel="invisible" hidden><p id="backgroundStatus">BACKGROUND: NOT CAPTURED</p><button id="capture">CAPTURE BACKGROUND</button><button id="clearBackground">CLEAR BACKGROUND</button>${range('gestureHold','GESTURE HOLD (ms)',200,1200,50)}${range('transitionDuration','TRANSITION (ms)',200,2000,50)}${range('edgeGlow','EDGE GLOW',0,30,1)}</div><div data-mode-panel="dissolve" hidden>${range('particles','PARTICLES',100,2000,50)}${range('speed','SPEED',.1,3,.1)}</div><div data-mode-panel="frame" hidden><label>PRESET<select data-setting="frameEffect"><option value="pop">NEON POP</option><option value="cmyk">CMYK</option><option value="mono">MONOCHROME</option><option value="pixel">CLASSIC PIXEL</option><option value="retro">RETRO 8-BIT</option></select></label>${range('pixelSize','PIXEL SIZE',2,32,1)}${range('colorDepth','COLOR DEPTH',2,8,1)}${color('borderColor','BORDER COLOR')}${range('borderWidth','BORDER THICKNESS',1,10,1)}</div><div data-mode-panel="twist" hidden><p>Two-hand masked frame is retained; 3D twist refinement is staged for the next release.</p>${range('edgeGlow','EDGE GLOW',0,30,1)}</div><div data-mode-panel="volume" hidden>${range('size','VOLUME SCALE',.4,2,.1)}${color('edgeColor','EDGE COLOR')}</div><div data-mode-panel="anime" hidden><label>PRESET<select data-setting="frameEffect"><option value="pop">CLASSIC ANIME</option><option value="mono">MANGA</option><option value="cmyk">NEON ANIME</option></select></label>${range('posterize','COLOR LEVELS',2,10,1)}${range('edgeGlow','EDGE GLOW',0,30,1)}</div><hr/><label class="check"><input data-setting="debug" type="checkbox"> LANDMARK DEBUG</label><label class="check"><input data-setting="mirror" type="checkbox"> MIRROR VIDEO</label><button id="reset">RESET SETTINGS</button><button id="export">EXPORT JSON</button><button id="import">IMPORT JSON</button><input id="importFile" type="file" accept="application/json" hidden/></aside></div><footer id="metrics">0 FPS · 0/2 HANDS · —</footer></section></main>`}
